return [
  { json: { name: "New Colleague A", role: "Sales Assistant", start: "2026-12-01", manager: "Team Lead" } },
  { json: { name: "New Colleague B", role: "Accountant", start: "2026-12-15", manager: "Financial Controller" } }
];

const TASKS = [
  { days: -7, task: "Order laptop and access", owner: "IT" },
  { days: -3, task: "Send welcome email with first-day agenda", owner: "HR" },
  { days: 0, task: "Welcome and team introduction", owner: "manager" },
  { days: 1, task: "Mandatory training (security, data protection)", owner: "HR" },
  { days: 30, task: "One-month feedback conversation", owner: "manager" }
];
const out = [];
for (const { json: h } of $input.all()) {
  const start = new Date(h.start + "T00:00:00Z");
  for (const t of TASKS) {
    const d = new Date(start); d.setUTCDate(d.getUTCDate() + t.days);
    // Weekend deadlines move to a working day: before the start date back to
    // Friday, from the start date on forward to Monday. Public holidays are not handled.
    const wd = d.getUTCDay();
    if (wd === 6) d.setUTCDate(d.getUTCDate() + (t.days < 0 ? -1 : 2));
    if (wd === 0) d.setUTCDate(d.getUTCDate() + (t.days < 0 ? -2 : 1));
    out.push({ json: { name: h.name, role: h.role, task: t.task, due: d.toISOString().slice(0, 10), owner: t.owner === "manager" ? h.manager : t.owner } });
  }
}
return out;
